import{_ as i,a as o,b as n}from"./chunks/PageInfo.vue_vue_type_script_setup_true_lang.BCVHfIj7.js";import{_ as s,c,I as e,a7 as l,o as h}from"./chunks/framework.DGCt2JJv.js";import"./chunks/dayjs.min.DZyl58SH.js";const k=JSON.parse('{"title":"Testing-Library 官网阅读笔记","description":"","frontmatter":{},"headers":[],"relativePath":"前端测试/Testing-Library 官网阅读笔记.md","filePath":"前端测试/Testing-Library 官网阅读笔记.md","lastUpdated":1722441511000}'),d={name:"前端测试/Testing-Library 官网阅读笔记.md"},p=l('<h1 id="testing-library-官网阅读笔记" tabindex="-1">Testing-Library 官网阅读笔记 <a class="header-anchor" href="#testing-library-官网阅读笔记" aria-label="Permalink to &quot;Testing-Library 官网阅读笔记&quot;">​</a></h1><h2 id="user-centric" tabindex="-1">user-centric <a class="header-anchor" href="#user-centric" aria-label="Permalink to &quot;user-centric&quot;">​</a></h2><p>1 不要尝试获取组件内部的state、method、lifecycle methods、child method（不同于enzyme，antd用的就是enzyme）</p><p>2 推荐你把data-testid写在组件代码里的，即使上生产环境也没关系（总会派上用场），实在不想要也可以用插件去掉。如果你就是不想用，也可以用普通的dom操作来查找</p><p>3 最好你要查的元素有role，不然就说明你的UI太inaccessible</p><h2 id="core-api" tabindex="-1">Core API <a class="header-anchor" href="#core-api" aria-label="Permalink to &quot;Core API&quot;">​</a></h2><h3 id="queries" tabindex="-1">Queries <a class="header-anchor" href="#queries" aria-label="Permalink to &quot;Queries&quot;">​</a></h3><p>get&quot;, &quot;find&quot;, &quot;query&quot;，区别在于找不到元素是否会报错、是否会返回promise ![](.Testing-Library 官网阅读笔记_images/39db1d62.png)</p><h3 id="priority" tabindex="-1">Priority <a class="header-anchor" href="#priority" aria-label="Permalink to &quot;Priority&quot;">​</a></h3><p>1 人人能理解的查询：getByRole、getByLabelText、getByPlaceholderText、getByText、getByDisplayValue</p><p>2 HTML5语义化查询和Aria选择器：getByAltText、getByTitle</p><p>3 getByTestId</p><h2 id="user-actions" tabindex="-1">User Actions <a class="header-anchor" href="#user-actions" aria-label="Permalink to &quot;User Actions&quot;">​</a></h2><h3 id="async-methods" tabindex="-1">Async Methods <a class="header-anchor" href="#async-methods" aria-label="Permalink to &quot;Async Methods&quot;">​</a></h3><h4 id="findby" tabindex="-1">findBy <a class="header-anchor" href="#findby" aria-label="Permalink to &quot;findBy&quot;">​</a></h4><p>findBy是getBy和waitFor的结合(e.g. await screen.findByText(&#39;text&#39;, queryOptions, waitForOptions)</p><h4 id="waitfor" tabindex="-1">waitFor <a class="header-anchor" href="#waitfor" aria-label="Permalink to &quot;waitFor&quot;">​</a></h4><p>1 默认循环时间是50ms，在循环开始之前会立即执行callback</p><p>2 默认超时时间是1000ms</p><p>3 循环直到callback条件满足，不会报错的时候</p><p>4 如果你在 waitFor callback中返回一个 Promise（显式或隐式地使用async语法），那么在该 Promise 拒绝之前，waitFor 不会再次调用你的callback。 This allows you to waitFor things that must be checked asynchronously.</p><p>5 使用MutationObserve比用waitFor定期轮询dom更高效</p><h3 id="fireevent注意事项" tabindex="-1">fireEvent注意事项 <a class="header-anchor" href="#fireevent注意事项" aria-label="Permalink to &quot;fireEvent注意事项&quot;">​</a></h3><p>Note</p><p>的确有些情况你需要用fireEvent，但是大多数请款给你应该使用@testing-library/user-event</p><p>根据the Guiding Principles，我们应该尽力去模仿真正的用户行为。</p><p>你要知道fireEvent并不是真正的代表用户交互行为，但是大多数情况下还是足够去模拟的。</p><p>比如当用户点击一个元素的时候，实际上触发的事件顺序是这样的：</p><p>● fireEvent.mouseOver(element) ● fireEvent.mouseMove(element) ● fireEvent.mouseDown(element) ● element.focus() (if that element is focusable) ● fireEvent.mouseUp(element) ● fireEvent.click(element)</p><p>如果说用户点的这个元素是lable的child，那么label标记的form control应该被focus。所以即使你想测的是click事件，但是如果你只是简单的使用fireEvent.click，你将会漏掉用户在此过程中触发的一系列重要事件。</p><p>再次声明，在大多数情况下，简单的使用fireEvent.click是值得的！</p><h2 id="contributors" tabindex="-1">Contributors <a class="header-anchor" href="#contributors" aria-label="Permalink to &quot;Contributors&quot;">​</a></h2>',32);function u(m,b,f,_,y,q){const t=i,a=o,r=n;return h(),c("div",null,[p,e(t,{readTime:"2",words:"566"}),e(a),e(r)])}const x=s(d,[["render",u]]);export{k as __pageData,x as default};
